-- Undo only the last presentation change, retaining product details and business data.
UPDATE site_settings SET body=json_remove(json_set(body,'$.shop.presentation','square','$.shop.layout','grid','$.shop.columns',3,'$.shop.tabletColumns',2,'$.shop.mobileColumns',2),'$.design'),version=version+1 WHERE id='appearance' AND json_extract(body,'$.design')='editorial';
--> statement-breakpoint
UPDATE puck_pages SET published=CASE WHEN published IS NULL THEN NULL ELSE json_set(published,'$.content',json((SELECT json_group_array(json(value)) FROM (SELECT CASE WHEN json_extract(block.value,'$.props.id')='Texte-initial-6' AND json_extract(block.value,'$.type')='Texte' THEN json_set(block.value,'$.props.level','h1') ELSE block.value END AS value FROM json_each(published,'$.content') block WHERE json_extract(block.value,'$.props.id')<>'editorial-introduction' ORDER BY CAST(block.key AS INTEGER))))) END,draft=CASE WHEN draft IS NULL THEN NULL ELSE json_set(draft,'$.content',json((SELECT json_group_array(json(value)) FROM (SELECT CASE WHEN json_extract(block.value,'$.props.id')='Texte-initial-6' AND json_extract(block.value,'$.type')='Texte' THEN json_set(block.value,'$.props.level','h1') ELSE block.value END AS value FROM json_each(draft,'$.content') block WHERE json_extract(block.value,'$.props.id')<>'editorial-introduction' ORDER BY CAST(block.key AS INTEGER))))) END,version=version+1 WHERE path='/' AND (instr(COALESCE(published,''),'editorial-introduction')>0 OR instr(COALESCE(draft,''),'editorial-introduction')>0);
